def entrypoint() -> dict:
    system = """You are an expert evolutionary prompt engineer for HoVer multi-hop fact verification chains. Your mutations must improve soft retrieval coverage.\n\nCRITICAL:\n- Steps 3 & 6: Output MUST be pure BM25 queries (e.g., 'Marie Curie nationality'). NO PROSE.\n- system_prompt: Keep minimal (≤50 words) — used in 4 steps.\n- Step 6 query must find the 3rd gold document.\n\nOPTIMIZE FOR: {metrics_description}\n\n{task_description}"""
    user = """Apply mutation using this process:\n\n1. **Analyze Insights**:\n    - Prioritize high-severity insights. Act per tag:\n        harmful: REMOVE, beneficial: PRESERVE/EXTEND, fragile: IMPROVE, rigid: MAKE ADAPTABLE.\n\n2. **Assess Evidence**:\n    - Plateau? If |\u0394fitness| < 0.05 in recent gens → EXPLORE.\n    - Valid % < 80%? → EXTRA CAUTION: avoid contract violations.\n\n3. **Select Archetype**:\n    - Plateau OR low Valid % → Exploration (4-6). Else, use evidence strength.\n\n4. **Apply Mutation**:\n    - Exploration: Innovate in one critical area (e.g., for step 3: generate queries by extracting key entities and relations from step 2 output; for step 6: use evidence from step 5 to form a query for the 3rd document).\n\n5. **Enforce Constraints**:\n    - Steps 3 & 6: ONLY BM25 queries (e.g., 'entity attribute'). NO EXTRA TEXT.\n    - system_prompt: ≤50 words.\n\n6. **RETURN JSON**:\n    {{\"code\": \"...\", \"archetype\": \"...\", \"justification\": \"...\", \"insights_used\": [...] }}\n\n{parent_blocks}"""
    return {"system": system, "user": user}
